    def bfs(queue, visited, parent):
        while queue:
            r, c = queue.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    parent[(nr, nc)] = (r, c)
                    queue.append((nr, nc))
                    if (nr, nc) == goal:
                        return True
        return False

    # BFS from start
    start_queue = deque()
    start_queue.append(start)
    start_visited = set([start])
    start_parent = {}

    if bfs(start_queue, start_visited, start_parent):
        path = []
        current = goal
        while current != start:
            path.append(current)
            current = start_parent[current]
        path.append(start)
        return path[::-1]

    # BFS from goal
    goal_queue = deque()
    goal_queue.append(goal)
    goal_visited = set([goal])
    goal_parent = {}

    if bfs(goal_queue, goal_visited, goal_parent):
        path = []
        current = start
        while current != goal:
            path.append(current)
            current = goal_parent[current]
        path.append(goal)
