from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) or
            0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def bfs(frontier, visited, other_visited, came_from):
        while frontier:
            row, col = frontier.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                r, c = row + dr, col + dc
                if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.' and (r,c) not in visited:
                    visited.add((r,c))
                    came_from[(r,c)] = (row, col)
                    if (r,c) in other_visited:
                        path = [(r,c)]
                        while (r,c) != start:
                            r, c = came_from[(r,c)]
                            path.append((r,c))
                        path.reverse()
                        return path
                    frontier.append((r,c))
        return []

    start_visited = set([start])
    goal_visited = set()
    start_queue = deque([start])
    goal_queue = deque([goal])
    start_came_from = {}
    goal_came_from = {}

    while start_queue and goal_queue:
        path = bfs(start_queue, start_visited, goal_visited, start_came_from)
        if path:
            return path
        path = bfs(goal_queue, goal_visited, start_visited, goal_came_from)
        if path:
            path = [(r,c) for (r,c) in path]
            path.reverse()
            return path
    return []
