from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Bidirectional BFS
    forward = deque([start])
    backward = deque([goal])

    forward_visited = {start: [start]}
    backward_visited = {goal: [goal]}

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    while forward and backward:
        # Forward search
        for _ in range(len(forward)):
            r, c = forward.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc):
                    if (nr, nc) in backward_visited:
                        return forward_visited[(r, c)] + backward_visited[(nr, nc)][::-1]
                    if (nr, nc) not in forward_visited:
                        forward_visited[(nr, nc)] = forward_visited[(r, c)] + [(nr, nc)]
                        forward.append((nr, nc))

        # Backward search
        for _ in range(len(backward)):
            r, c = backward.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc):
                    if (nr, nc) in forward_visited:
                        return forward_visited[(nr, nc)] + backward_visited[(r, c)][::-1]
                    if (nr, nc) not in backward_visited:
                        backward_visited[(nr, nc)] = backward_visited[(r, c)] + [(nr, nc)]
                        backward.append((nr, nc))

    return []
