                    visited.add((r, c))
                    queue.append(((r, c), path + [(r, c)]))
        return []

    start_set = set([start])
    goal_set = set([goal])
    start_visited = set([start])
    goal_visited = set([goal])

    while start_set and goal_set:
        if len(start_set) > len(goal_set):
            result = bfs(goal, start_set, start_visited)
            if result:
                return result
            start_set, goal_set = goal_set, start_set
            start_visited, goal_visited = goal_visited, start_visited
