    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start, goal, visited, parent):
        queue = deque()
        queue.append(start)
        visited.add(start)
        parent[start] = None

        while queue:
            current = queue.popleft()
            if current == goal:
                return True
            for dr, dc in directions:
                nr, nc = current[0] + dr, current[1] + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    parent[(nr, nc)] = current
                    queue.append((nr, nc))
        return False

    forward_visited = set()
    backward_visited = set()
    forward_parent = {}
    backward_parent = {}

    forward_bfs = bfs(start, goal, forward_visited, forward_parent)
    backward_bfs = bfs(goal, start, backward_visited, backward_parent)

    if not forward_bfs or not backward_bfs:
        return []

    # Find the intersection point
    intersection = None
    for point in forward_visited:
        if point in backward_visited:
            intersection = point
            break

    if not intersection:
        return []

    # Reconstruct path from start to intersection
    path = []
    current = intersection
    while current:
        path.append(current)
        current = forward_parent.get(current)

    # Reconstruct path from intersection to goal
    current = intersection
    while current != goal:
        current = backward_parent.get(current)
        if current:
