                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited:
                    visited.add((r, c))
                    stack.append(( (r, c), path + [(r, c)], depth + 1 ))
            if depth == max_depth:
                found = True
        if found:
            max_depth += 1
        else:
