import heapq

def solve(grid, start, goal):
    if not grid or start == goal:
        # Check if start is a free cell
        if 0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    heap = [(0, start[0], start[1], [start])]

    while heap:
        _, r, c, path = heapq.heappop(heap)
        if (r, c) == goal:
            return path
        if (r, c) in visited:
            continue
        visited.add((r, c))

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                new_path = path + [(nr, nc)]
                # For A*, use Manhattan distance as heuristic
                heuristic = abs(nr - goal[0]) + abs(nc - goal[1])
                heapq.heappush(heap, (len(new_path) + heuristic, nr, nc, new_path))

    return []
