    reversed_graph = [[] for _ in range(n)]
    for u, v, w in edges:
        reversed_graph[v].append((u, w))

    # Dijkstra from t in reversed graph
    def dijkstra_reversed(start):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in reversed_graph[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
