import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm with priority queue
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            d, u = heapq.heappop(heap)
            if u == end:
                return d
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return -1

    # Bidirectional Dijkstra
    def bidirectional_dijkstra(start, end):
        dist_from_start = [float('inf')] * n
        dist_from_end = [float('inf')] * n
        dist_from_start[start] = 0
        dist_from_end[end] = 0

        heap_start = [(0, start)]
        heap_end = [(0, end)]

        while heap_start and heap_end:
            # Expand from start
            d_start, u = heapq.heappop(heap_start)
            if d_start > dist_from_start[u]:
                continue
            for v, w in graph[u]:
                if dist_from_start[v] > d_start + w:
                    dist_from_start[v] = d_start + w
                    heapq.heappush(heap_start, (dist_from_start[v], v))
                if dist_from_end[v] != float('inf'):
                    return dist_from_start[u] + dist_from_end[v]

            # Expand from end (reverse graph)
            d_end, u = heapq.heappop(heap_end)
            if d_end > dist_from_end[u]:
                continue
            for v, w in graph[u]:
                if dist_from_end[v] > d_end + w:
                    dist_from_end[v] = d_end + w
                    heapq.heappush(heap_end, (dist_from_end[v], v))
                if dist_from_start[v] != float('inf'):
                    return dist_from_start[v] + dist_from_end[u]

        return -1

    return bidirectional_dijkstra(s, t)
