    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm with priority queue
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            curr_dist, u = heapq.heappop(heap)
            if u == end:
                return curr_dist
            if curr_dist > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > curr_dist + w:
                    dist[v] = curr_dist + w
                    heapq.heappush(heap, (dist[v], v))
        return -1

    # Bidirectional Dijkstra
    dist_from_s = [float('inf')] * n
    dist_from_t = [float('inf')] * n
    heap_s = [(0, s)]
    heap_t = [(0, t)]
    dist_from_s[s] = 0
    dist_from_t[t] = 0

    while heap_s and heap_t:
        # Expand from s
        curr_dist_s, u = heapq.heappop(heap_s)
        if curr_dist_s > dist_from_s[u]:
            continue
        for v, w in adj[u]:
            if dist_from_s[v] > curr_dist_s + w:
                dist_from_s[v] = curr_dist_s + w
                heapq.heappush(heap_s, (dist_from_s[v], v))

        # Expand from t (reverse graph)
        curr_dist_t, u = heapq.heappop(heap_t)
        if curr_dist_t > dist_from_t[u]:
            continue
        for v, w in adj[u]:
            if dist_from_t[v] > curr_dist_t + w:
                dist_from_t[v] = curr_dist_t + w
                heapq.heappush(heap_t, (dist_from_t[v], v))

        # Check for meeting point
        if dist_from_s[t] < float('inf') and dist_from_t[s] < float('inf'):
            return dist_from_s[t] + dist_from_t[s]

    return -1
