            if visited_s[u]:
                continue
            visited_s[u] = True
            for v, w in graph[u]:
                if dist_from_s[v] > d + w:
                    dist_from_s[v] = d + w
                    heapq.heappush(heap_s, (dist_from_s[v], v))
            # Check if we meet from the other side
            if visited_t[u]:
                return dist_from_s[u] + dist_from_t[u]

            # Expand from t
            d, u = heapq.heappop(heap_t)
            if visited_t[u]:
                continue
            visited_t[u] = True
            for v, w in graph[u]:
                if dist_from_t[v] > d + w:
                    dist_from_t[v] = d + w
                    heapq.heappush(heap_t, (dist_from_t[v], v))
            # Check if we meet from the other side
            if visited_s[u]:
                return dist_from_s[u] + dist_from_t[u]

        # Check if t is reachable from s
        if dist_from_s[t] != float('inf'):
            return dist_from_s[t]
        return -1

    return bidirectional_dijkstra(s, t)
