import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            d, u = heapq.heappop(heap)
            if u == end:
                return d
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return -1

    # Bidirectional Dijkstra
    def bidirectional_dijkstra(s, t):
        dist_from_s = [float('inf')] * n
        dist_from_t = [float('inf')] * n
        heap_s = [(0, s)]
        heap_t = [(0, t)]
        dist_from_s[s] = 0
        dist_from_t[t] = 0

        while heap_s and heap_t:
            # Expand from s
            d_s, u = heapq.heappop(heap_s)
            if d_s > dist_from_s[u]:
                continue
            for v, w in adj[u]:
                if dist_from_s[v] > d_s + w:
                    dist_from_s[v] = d_s + w
                    heapq.heappush(heap_s, (dist_from_s[v], v))
                if dist_from_t[v] != float('inf'):
                    return dist_from_s[u] + dist_from_t[v]

            # Expand from t
            d_t, u = heapq.heappop(heap_t)
            if d_t > dist_from_t[u]:
                continue
            for v, w in adj[u]:
                if dist_from_t[v] > d_t + w:
                    dist_from_t[v] = d_t + w
                    heapq.heappush(heap_t, (dist_from_t[v], v))
                if dist_from_s[v] != float('inf'):
                    return dist_from_s[v] + dist_from_t[u]

        return -1

    return bidirectional_dijkstra(s, t)
