import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm with bidirectional approach
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            curr_dist, u = heapq.heappop(heap)
            if u == end:
                return curr_dist
            if curr_dist > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(heap, (dist[v], v))
        return -1

    # Bidirectional Dijkstra
    dist_s = [float('inf')] * n
    dist_t = [float('inf')] * n
    heap_s = [(0, s)]
    heap_t = [(0, t)]
    dist_s[s] = 0
    dist_t[t] = 0

    while heap_s and heap_t:
        # From s
        curr_dist, u = heapq.heappop(heap_s)
        if u == t:
            return curr_dist
        if curr_dist > dist_s[u]:
            continue
        for v, w in graph[u]:
            if dist_s[v] > dist_s[u] + w:
                dist_s[v] = dist_s[u] + w
                heapq.heappush(heap_s, (dist_s[v], v))

        # From t (reverse graph)
        curr_dist, u = heapq.heappop(heap_t)
        if u == s:
            return curr_dist
        if curr_dist > dist_t[u]:
            continue
        for v, w in graph[u]:
            if dist_t[v] > dist_t[u] + w:
                dist_t[v] = dist_t[u] + w
                heapq.heappush(heap_t, (dist_t[v], v))

    return -1
