import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm with bidirectional search
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        prev = [-1] * n

        while heap:
            d, u = heapq.heappop(heap)
            if u == end:
                break
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    prev[v] = u
                    heapq.heappush(heap, (dist[v], v))
        return dist[end], prev

    # Bidirectional Dijkstra
    dist_from_s, _ = dijkstra(s, t)
    dist_from_t, _ = dijkstra(t, s)

    # Check if t is reachable from s
    if dist_from_s == float('inf'):
        return -1

    # Now perform bidirectional search
    # From s towards t and from t towards s
    # Use two priority queues
    def bidirectional_dijkstra(s, t):
        dist_s = [float('inf')] * n
        dist_t = [float('inf')] * n
        dist_s[s] = 0
        dist_t[t] = 0
        heap_s = [(0, s)]
        heap_t = [(0, t)]
        prev_s = [-1] * n
        prev_t = [-1] * n
        visited = [False] * n

        while heap_s and heap_t:
            # Expand from s
            d_s, u = heapq.heappop(heap_s)
            if visited[u]:
                continue
            visited[u] = True
            if u == t:
                break
            for v, w in adj[u]:
                if dist_s[v] > d_s + w:
                    dist_s[v] = d_s + w
                    prev_s[v] = u
                    heapq.heappush(heap_s, (dist_s[v], v))

            # Expand from t
            d_t, v = heapq.heappop(heap_t)
            if visited[v]:
                continue
            visited[v] = True
            if v == s:
                break
            for u, w in adj:
                if u == v:
                    for w_uv in adj[v]:
                        u2, w2 = w_uv
                        if dist_t[u2] > d_t + w2:
                            dist_t[u2] = d_t + w2
                            prev_t[u2] = v
                            heapq.heappush(heap_t, (dist_t[u2], u2))

        # Reconstruct path from s to t
        if dist_s[t] == float('inf'):
            return -1
        return dist_s[t]

    return bidirectional_dijkstra(s, t)
